+#ifndef __MTK_DPI_REGS_H
+#define __MTK_DPI_REGS_H
+
+#define DVO_EN			0x00
+#define EN				BIT(0)
+#define DVO_FORCE_ON			BIT(4)
+#define LINK_OFF			BIT(8)
